use frame_support::weights::Weight;
use core::marker::PhantomData;

/// Weight functions needed for `pallet_gpu_pow`.
pub trait WeightInfo {
    fn submit_solution() -> Weight;
    fn set_block_beneficiary() -> Weight;
}

/// Weights for `pallet_gpu_pow` using the GPN node and recommended hardware.
pub struct SubstrateWeight<T>(PhantomData<T>);
impl<T: frame_system::Config> WeightInfo for SubstrateWeight<T> {
    /// Storage: `GpuPow::CurrentBlockReward` (r:1 w:0); `GpuPow::PendingBlockRewards` (w:1);
    /// `GpuPow::PendingRewardBeneficiary` (w:1).
    fn submit_solution() -> Weight {
        Weight::from_parts(10_000, 0)
    }

    /// Storage: `GpuPow::BlockRewardBeneficiary` (w:1).
    fn set_block_beneficiary() -> Weight {
        Weight::from_parts(10_000, 0)
    }
}

// For backwards compatibility and tests.
impl WeightInfo for () {
    fn submit_solution() -> Weight {
        Weight::from_parts(10_000, 0)
    }

    fn set_block_beneficiary() -> Weight {
        Weight::from_parts(10_000, 0)
    }
}
